def normalize_proxy_template(template: str) -> str:
    """Template proksi yang dinormalisasi, mendukung berbagai format:
    - Standar: user:pass@host:port
    - Terbalik: host:port@user:pass
    - Dipisah titik dua: host:port:user:pass
    """
    proxy = str(template or "").strip()
    if not proxy:
        return proxy

    if "@" not in proxy:
        parts = proxy.split(":")
        if len(parts) == 4:
            host, port, user, pwd = parts
            if "." in host and port.isdigit():
                return normalize_proxy_url(f"{user}:{pwd}@{host}:{port}")
        return normalize_proxy_url(proxy)

    parts = proxy.split("@")
    if len(parts) != 2:
        return normalize_proxy_url(proxy)
    left, right = parts
    if re.match(r"^[a-zA-Z0-9.\-]+:\d+$", left) and "." in left.split(":")[0]:
        return normalize_proxy_url(f"{right}@{left}")
    return normalize_proxy_url(proxy)


